package runtime

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"syscall"
	"time"
)

const RuntimeStoreDirName = "runtime/opencode"

type RuntimeStoreState string

const (
	RuntimeStoreActive         RuntimeStoreState = "active"
	RuntimeStoreRetained       RuntimeStoreState = "retained"
	RuntimeStoreCleanupPending RuntimeStoreState = "cleanup_pending"
)

type RuntimeStoreRecord struct {
	SchemaVersion int               `json:"schema_version"`
	Owner         string            `json:"owner"`
	DatabasePath  string            `json:"database_path"`
	State         RuntimeStoreState `json:"state"`
	PID           int               `json:"pid,omitempty"`
	CreatedAt     time.Time         `json:"created_at"`
	UpdatedAt     time.Time         `json:"updated_at"`
	LastError     string            `json:"last_error,omitempty"`
}

type RuntimeStoreInfo struct {
	RuntimeStoreRecord
	Bytes uint64 `json:"bytes"`
}

type RuntimeStoreCleanup struct {
	Removed []RuntimeStoreInfo `json:"removed,omitempty"`
	Failed  []string           `json:"failed,omitempty"`
}

func ScopedRuntimeStorePath(scopeRoot, owner string) string {
	sum := sha256.Sum256([]byte(strings.TrimSpace(owner)))
	return filepath.Join(scopeRoot, ".ultraplan", RuntimeStoreDirName, hex.EncodeToString(sum[:16]), "opencode.db")
}

func prepareRuntimeStore(path, owner string) error {
	dir, err := validatedRuntimeStoreDir(path)
	if err != nil {
		return err
	}
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return fmt.Errorf("create runtime store: %w", err)
	}
	now := time.Now().UTC()
	record := RuntimeStoreRecord{SchemaVersion: 1, Owner: owner, DatabasePath: path, State: RuntimeStoreActive, PID: os.Getpid(), CreatedAt: now, UpdatedAt: now}
	if previous, err := loadRuntimeStoreRecord(dir); err == nil {
		record.CreatedAt = previous.CreatedAt
	}
	return writeRuntimeStoreRecord(dir, record)
}

func retainRuntimeStore(path, owner string, runErr error) {
	if strings.TrimSpace(path) == "" {
		return
	}
	dir, err := validatedRuntimeStoreDir(path)
	if err != nil {
		return
	}
	record, loadErr := loadRuntimeStoreRecord(dir)
	if loadErr != nil {
		now := time.Now().UTC()
		record = RuntimeStoreRecord{SchemaVersion: 1, Owner: owner, DatabasePath: path, CreatedAt: now}
	}
	record.State = RuntimeStoreRetained
	record.PID = 0
	record.UpdatedAt = time.Now().UTC()
	if runErr != nil {
		record.LastError = runErr.Error()
	}
	_ = writeRuntimeStoreRecord(dir, record)
}

func markRuntimeStoreCleanupPending(path string, cleanupErr error) {
	dir, err := validatedRuntimeStoreDir(path)
	if err != nil {
		return
	}
	record, err := loadRuntimeStoreRecord(dir)
	if err != nil {
		return
	}
	record.State = RuntimeStoreCleanupPending
	record.PID = 0
	record.UpdatedAt = time.Now().UTC()
	if cleanupErr != nil {
		record.LastError = cleanupErr.Error()
	}
	_ = writeRuntimeStoreRecord(dir, record)
}

func removeRuntimeStore(path string) error {
	dir, err := validatedRuntimeStoreDir(path)
	if err != nil {
		return err
	}
	if err := os.RemoveAll(dir); err != nil {
		return fmt.Errorf("remove runtime store %s: %w", dir, err)
	}
	return nil
}

func validatedRuntimeStoreDir(path string) (string, error) {
	clean := filepath.Clean(strings.TrimSpace(path))
	if !filepath.IsAbs(clean) || filepath.Base(clean) != "opencode.db" {
		return "", fmt.Errorf("invalid runtime store path %q", path)
	}
	dir := filepath.Dir(clean)
	marker := string(filepath.Separator) + filepath.FromSlash(".ultraplan/"+RuntimeStoreDirName) + string(filepath.Separator)
	if !strings.Contains(dir+string(filepath.Separator), marker) {
		return "", fmt.Errorf("runtime store is outside managed storage: %q", path)
	}
	return dir, nil
}

func loadRuntimeStoreRecord(dir string) (RuntimeStoreRecord, error) {
	data, err := os.ReadFile(filepath.Join(dir, "store.json"))
	if err != nil {
		return RuntimeStoreRecord{}, err
	}
	var record RuntimeStoreRecord
	if err := json.Unmarshal(data, &record); err != nil {
		return RuntimeStoreRecord{}, err
	}
	if record.SchemaVersion != 1 {
		return RuntimeStoreRecord{}, errors.New("unsupported runtime store record")
	}
	return record, nil
}

func writeRuntimeStoreRecord(dir string, record RuntimeStoreRecord) error {
	data, err := json.MarshalIndent(record, "", "  ")
	if err != nil {
		return err
	}
	data = append(data, '\n')
	tmp, err := os.CreateTemp(dir, ".store.*.tmp")
	if err != nil {
		return err
	}
	name := tmp.Name()
	defer os.Remove(name)
	if _, err = tmp.Write(data); err == nil {
		err = tmp.Chmod(0o600)
	}
	if closeErr := tmp.Close(); err == nil {
		err = closeErr
	}
	if err != nil {
		return err
	}
	return os.Rename(name, filepath.Join(dir, "store.json"))
}

func InspectRuntimeStores(scopeRoot string) ([]RuntimeStoreInfo, error) {
	root := filepath.Join(scopeRoot, ".ultraplan", RuntimeStoreDirName)
	entries, err := os.ReadDir(root)
	if errors.Is(err, os.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	stores := make([]RuntimeStoreInfo, 0, len(entries))
	for _, entry := range entries {
		if !entry.IsDir() {
			continue
		}
		dir := filepath.Join(root, entry.Name())
		record, err := loadRuntimeStoreRecord(dir)
		if err != nil {
			continue
		}
		stores = append(stores, RuntimeStoreInfo{RuntimeStoreRecord: record, Bytes: directoryBytes(dir)})
	}
	sort.Slice(stores, func(i, j int) bool { return stores[i].UpdatedAt.Before(stores[j].UpdatedAt) })
	return stores, nil
}

// CleanupRuntimeStores retries interrupted cleanup, expires abandoned stores,
// and optionally sacrifices retained sessions under critical disk pressure.
func CleanupRuntimeStores(scopeRoot string, maxAge time.Duration, maxBytes uint64, aggressive bool) RuntimeStoreCleanup {
	stores, err := InspectRuntimeStores(scopeRoot)
	if err != nil {
		return RuntimeStoreCleanup{Failed: []string{err.Error()}}
	}
	now := time.Now().UTC()
	var total uint64
	for _, store := range stores {
		total += store.Bytes
	}
	result := RuntimeStoreCleanup{}
	for _, store := range stores {
		staleActive := store.State == RuntimeStoreActive && !processAlive(store.PID) && now.Sub(store.UpdatedAt) > 30*time.Minute
		if staleActive {
			// A dead owner means an interrupted task, not disposable data. Keep the
			// database resumable and let the normal retention/quota policy decide
			// when it is safe to sacrifice it.
			retainRuntimeStore(store.DatabasePath, store.Owner, errors.New("runtime store owner is no longer running"))
			store.State = RuntimeStoreRetained
			store.PID = 0
			store.UpdatedAt = now
		}
		expired := store.State == RuntimeStoreRetained && maxAge > 0 && now.Sub(store.UpdatedAt) > maxAge
		overQuota := maxBytes > 0 && total > maxBytes && store.State != RuntimeStoreActive
		remove := store.State == RuntimeStoreCleanupPending || expired || overQuota || (aggressive && store.State != RuntimeStoreActive)
		if !remove {
			continue
		}
		if err := removeRuntimeStore(store.DatabasePath); err != nil {
			result.Failed = append(result.Failed, err.Error())
			continue
		}
		result.Removed = append(result.Removed, store)
		if store.Bytes <= total {
			total -= store.Bytes
		}
	}
	return result
}

func processAlive(pid int) bool {
	if pid < 1 {
		return false
	}
	return syscall.Kill(pid, 0) == nil
}

func directoryBytes(root string) uint64 {
	var total uint64
	_ = filepath.WalkDir(root, func(_ string, entry os.DirEntry, err error) error {
		if err != nil || entry.IsDir() {
			return nil
		}
		if info, statErr := entry.Info(); statErr == nil && info.Size() > 0 {
			total += uint64(info.Size())
		}
		return nil
	})
	return total
}

package runtime

import (
	"context"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"
	"time"

	"github.com/Antonio7098/agentwrap"
	"github.com/Antonio7098/agentwrap/opencode"

	"github.com/Antonio7098/ultraplan-go/internal/platform/config"
)

var openCodeSessionCleanupMu sync.Mutex

// rateSnapshotDir returns the cache directory holding the model-rate snapshot
// shared across runs. An empty result disables persistence (memory-only).
func rateSnapshotDir() string {
	cache, err := os.UserCacheDir()
	if err != nil || cache == "" {
		return ""
	}
	return filepath.Join(cache, "ultraplan")
}

func NewOpenCode(c config.Config) (Adapter, error) {
	rateStore := agentwrap.NewRateTableStore(rateSnapshotDir())
	newRuntime := func(extraArgs ...string) *opencode.Runtime {
		args := append([]string(nil), c.Agentwrap.ExtraArgs...)
		args = append(args, extraArgs...)
		return opencode.NewRuntime(
			opencode.WithExecutable(c.Agentwrap.Executable),
			opencode.WithExtraArgs(args...),
			opencode.WithEnv(c.Agentwrap.Env...),
			opencode.WithSnapshots(false),
			opencode.WithStderrLimit(c.Agentwrap.StderrLimit),
			opencode.WithRateTableStore(rateStore),
		)
	}
	primary := newRuntime()
	stageRuntime := requestVariantRuntime{
		base: primary,
		withVariant: func(variant string) agentwrap.Runtime {
			return newRuntime("--variant", variant)
		},
	}
	policy := agentwrap.BasicPolicy{
		MaxAttemptsPerTarget: c.Execution.DefaultRetries + 1,
		Backoff:              agentwrap.ExponentialBackoff{Initial: time.Second, Factor: 2, Max: 30 * time.Second},
		RetryRateLimits:      true,
	}
	if c.Models.Backup != "" && c.Models.Backup != c.Models.Primary {
		provider, model := splitModel(c.Models.Backup)
		policy.Fallbacks = []agentwrap.FallbackAlternative{{
			Name: "backup",
			Request: agentwrap.RunRequest{
				Provider: agentwrap.ProviderID(provider),
				Model:    agentwrap.ModelID(model),
			},
			Context: agentwrap.RuntimeContext{
				RuntimeKind: "opencode",
				RuntimeName: "opencode",
				Provider:    agentwrap.ProviderID(provider),
				Model:       agentwrap.ModelID(model),
			},
		}}
	}
	stack := agentwrap.ObservingRuntime{
		Runtime: agentwrap.ValidatingRuntime{
			Runtime: agentwrap.PolicyRunner{
				Runtime: stageRuntime,
				Policy:  missingSessionPolicy{next: policy},
			},
		},
		Policy: agentwrap.PersistencePolicy{PersistUnsafeRawPayloads: false},
	}
	adapter := Adapter{runtime: stack, health: primary}
	adapter.deleteRuntimeStore = func(_ context.Context, path string) error {
		if err := removeRuntimeStore(path); err != nil {
			markRuntimeStoreCleanupPending(path, err)
			return err
		}
		openCodeSessionCleanupMu.Lock()
		_ = pruneOpenCodeLogs(c)
		openCodeSessionCleanupMu.Unlock()
		return nil
	}
	adapter.deleteSessions = func(ctx context.Context, sessionIDs []string) error {
		openCodeSessionCleanupMu.Lock()
		defer openCodeSessionCleanupMu.Unlock()

		for _, sessionID := range sessionIDs {
			if strings.TrimSpace(sessionID) == "" {
				continue
			}
			// OpenCode stores its event stream under an aggregate whose ID is the
			// session ID, but event_sequence has no foreign key back to session.
			query := "DELETE FROM event_sequence WHERE aggregate_id = " + sqliteString(sessionID)
			if output, err := openCodeDBCommand(ctx, c, query).CombinedOutput(); err != nil {
				return fmt.Errorf("delete OpenCode session events %s: %w: %s", sessionID, err, strings.TrimSpace(string(output)))
			}
			cmd := exec.CommandContext(ctx, c.Agentwrap.Executable, "session", "delete", sessionID)
			cmd.Env = append(os.Environ(), c.Agentwrap.Env...)
			if output, err := cmd.CombinedOutput(); err != nil {
				return fmt.Errorf("delete OpenCode session %s: %w: %s", sessionID, err, strings.TrimSpace(string(output)))
			}
		}
		if err := checkpointOpenCode(ctx, c); err != nil {
			return fmt.Errorf("checkpoint OpenCode database: %w", err)
		}
		if output, err := openCodeDBCommand(ctx, c, "VACUUM").CombinedOutput(); err != nil {
			return fmt.Errorf("vacuum OpenCode database: %w: %s", err, strings.TrimSpace(string(output)))
		}
		// In WAL mode VACUUM writes the compacted image to the WAL. Checkpoint it
		// before the next worker wave starts so the temporary copy is removed.
		if err := checkpointOpenCode(ctx, c); err != nil {
			return fmt.Errorf("checkpoint vacuumed OpenCode database: %w", err)
		}
		return nil
	}
	return adapter, nil
}

type missingSessionPolicy struct {
	next agentwrap.ResiliencePolicy
}

func (p missingSessionPolicy) Decide(ctx context.Context, policyCtx agentwrap.PolicyContext) (agentwrap.PolicyDecision, error) {
	if openCodeSessionNotFound(policyCtx.Err) {
		return agentwrap.PolicyDecision{Kind: agentwrap.PolicyDecisionStop, Reason: "session not found", Detail: policyCtx.Err.UserDetail, Err: policyCtx.Err}, nil
	}
	return p.next.Decide(ctx, policyCtx)
}

func openCodeSessionNotFound(err *agentwrap.SDKError) bool {
	if err == nil {
		return false
	}
	details := []string{err.UserDetail, err.DebugDetail, err.ResponseBody}
	if err.Cause != nil {
		details = append(details, err.Cause.Error())
	}
	return strings.Contains(strings.ToLower(strings.Join(details, "\n")), "session not found")
}

func checkpointOpenCode(ctx context.Context, c config.Config) error {
	var detail string
	for attempt := 0; attempt < 20; attempt++ {
		output, err := openCodeDBCommand(ctx, c, "PRAGMA wal_checkpoint(TRUNCATE)").CombinedOutput()
		detail = strings.TrimSpace(string(output))
		if err == nil {
			fields := strings.Fields(detail)
			if len(fields) >= 3 && fields[len(fields)-3] == "0" {
				return nil
			}
		}
		if err := sleepContext(ctx, 250*time.Millisecond); err != nil {
			return err
		}
	}
	return fmt.Errorf("database remained busy: %s", detail)
}

func sleepContext(ctx context.Context, delay time.Duration) error {
	timer := time.NewTimer(delay)
	defer timer.Stop()
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-timer.C:
		return nil
	}
}

func openCodeDBCommand(ctx context.Context, c config.Config, query string) *exec.Cmd {
	cmd := exec.CommandContext(ctx, c.Agentwrap.Executable, "db", query)
	cmd.Env = append(os.Environ(), c.Agentwrap.Env...)
	return cmd
}

func sqliteString(value string) string {
	return "'" + strings.ReplaceAll(value, "'", "''") + "'"
}

// requestVariantRuntime translates UltraPlan's stage-specific variant metadata
// into an adapter invocation. agentwrap deliberately keeps request metadata
// runtime-neutral, while OpenCode exposes reasoning effort as --variant.
type requestVariantRuntime struct {
	base        agentwrap.Runtime
	withVariant func(string) agentwrap.Runtime
}

func (r requestVariantRuntime) StartRun(ctx context.Context, req agentwrap.RunRequest) (agentwrap.Run, error) {
	variant := strings.TrimSpace(req.Metadata["variant"])
	if variant == "" || r.withVariant == nil {
		return r.base.StartRun(ctx, req)
	}
	return r.withVariant(variant).StartRun(ctx, req)
}

func (r requestVariantRuntime) Capabilities(ctx context.Context) (agentwrap.Capabilities, error) {
	return r.base.Capabilities(ctx)
}

// ListModels forwards model enumeration to the primary runtime when it
// supports the optional listing capability.
func (r requestVariantRuntime) ListModels(ctx context.Context, req agentwrap.ModelsRequest) ([]agentwrap.ModelInfo, error) {
	lister, ok := r.base.(agentwrap.ModelLister)
	if !ok {
		return nil, nil
	}
	return lister.ListModels(ctx, req)
}

}

func NewAdapter(aw agentwrap.Runtime) Adapter {
	a := Adapter{runtime: aw}
	if h, ok := aw.(agentwrap.HealthChecker); ok {
		a.health = h
	}
	return a
}

func (a Adapter) StartRun(ctx context.Context, req Request) (Result, error) {
	if a.runtime == nil {
		return Result{}, fmt.Errorf("runtime is required")
	}
	if req.RuntimeStorePath != "" {
		if err := prepareRuntimeStore(req.RuntimeStorePath, req.RuntimeStoreOwner); err != nil {
			return Result{RuntimeStorePath: req.RuntimeStorePath}, err
		}
	}
	awReq, err := toAgentwrapRequest(req)
	if err != nil {
		retainRuntimeStore(req.RuntimeStorePath, req.RuntimeStoreOwner, err)
		return Result{RuntimeStorePath: req.RuntimeStorePath}, err
	}
	run, err := a.runtime.StartRun(ctx, awReq)
	if err != nil {
		mappedErr := mapError(err)
		retainRuntimeStore(req.RuntimeStorePath, req.RuntimeStoreOwner, mappedErr)
		return Result{RuntimeStorePath: req.RuntimeStorePath}, mappedErr
	}

	eventsCh := make(chan eventCollection, 1)
	go func() {
		events := newEventCollection(retainedRuntimeEventLimit)
		for event := range run.Events() {
			events.captureTerminalOutput(event.Payload)
			mapped := mapEvent(event)
			events.add(mapped)
			if req.OnEvent != nil {
				req.OnEvent(mapped)
			}
		}
		events.finish()
		eventsCh <- events
	}()

	type waitResult struct {
		result agentwrap.RunResult
		err    error
	}
	waitCh := make(chan waitResult, 1)
	go func() {
		result, err := run.Wait(ctx)
		waitCh <- waitResult{result: result, err: err}
	}()

	var result agentwrap.RunResult
	var waitErr error
	select {
	case waited := <-waitCh:
		result = waited.result
		waitErr = waited.err
	case <-ctx.Done():
		_ = run.Cancel(context.Background())
		select {
		case waited := <-waitCh:
			result = waited.result
			waitErr = waited.err
		case <-time.After(5 * time.Second):
			mapped := Result{
				Status:           "cancelled",
				FinishedAt:       time.Now(),
				Error:            &Error{Category: "cancellation", Operation: "run", UserDetail: ctx.Err().Error()},
				RuntimeStorePath: req.RuntimeStorePath,
			}
			retainRuntimeStore(req.RuntimeStorePath, req.RuntimeStoreOwner, ctx.Err())
			return mapped, ctx.Err()
		}
		if waitErr == nil {
			waitErr = ctx.Err()
		}
	}

	mapped := mapResult(result)
	mapped.RuntimeStorePath = req.RuntimeStorePath
	select {
	case events := <-eventsCh:
		mapped.Events = events.events
		if mapped.TerminalOutput == "" && events.terminalOutput != "" {
			mapped.TerminalOutput = events.terminalOutput
		}
		mapped.EventStats = events.stats()
		mapped.Memory = events.memory
		mapped.SessionIDs = append([]string(nil), events.sessionIDs...)
		if mapped.SessionID != "" && !events.seenSessions[mapped.SessionID] {
			mapped.SessionIDs = append(mapped.SessionIDs, mapped.SessionID)
		}
		if events.dropped > 0 {
			mapped.Warnings = append(mapped.Warnings, fmt.Sprintf("runtime retained last %d events and dropped %d earlier events from in-memory result", events.limit, events.dropped))
		}
	case <-time.After(time.Second):
	}
	if waitErr != nil {
		retainRuntimeStore(req.RuntimeStorePath, req.RuntimeStoreOwner, waitErr)
		if errors.Is(waitErr, context.Canceled) {
			mapped.Status = "cancelled"
			mapped.Error = &Error{Category: "cancellation", Operation: "run", UserDetail: waitErr.Error()}
		} else if errors.Is(waitErr, context.DeadlineExceeded) {
			mapped.Status = "failed"
			mapped.Error = &Error{Category: "timeout", Operation: "run", UserDetail: waitErr.Error()}
		}
		return mapped, mapError(waitErr)
	}
	if result.Err != nil {
		retainRuntimeStore(req.RuntimeStorePath, req.RuntimeStoreOwner, result.Err)
		return mapped, mapError(result.Err)
	}
	retainRuntimeStore(req.RuntimeStorePath, req.RuntimeStoreOwner, nil)
	return mapped, nil
}

type eventCollection struct {
	events         []Event
	terminalOutput string
	total          int64
	dropped        int64
	limit          int
	memory         MemoryStats
	sessionIDs     []string
	seenSessions   map[string]bool
}

func newEventCollection(limit int) eventCollection {
	if limit < 0 {
		limit = 0
	}
	var mem stdruntime.MemStats
	stdruntime.ReadMemStats(&mem)
	return eventCollection{
		events:       make([]Event, 0, limit),
		limit:        limit,
		seenSessions: map[string]bool{},
		memory: MemoryStats{
			StartAllocBytes: mem.Alloc,
			PeakAllocBytes:  mem.Alloc,
			Samples:         1,
		},
	}
}

